import{_ as a,a0 as s,w as e,s as l,ao as p,I as n,x as o,a1 as r,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const V=JSON.parse('{"title":"安卓编年史（30）：Android TV 和 Android Auto | LCTT x X-CMD","titleTemplate":false,"description":"安卓编年史（30）：Android TV 和 Android Auto | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓编年史（30）：Android TV 和 Android Auto | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓编年史（30）：Android TV 和 Android Auto | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/30 - The (updated) history of Android","title":"安卓编年史（30）：Android TV 和 Android Auto","tag":"The history of Android","desc":""},"relativePath":"The history of Android/30 - The (updated) history of Android.md","filePath":"[post].md"}'),u={name:"The history of Android/30 - The (updated) history of Android.md"};function A(m,t,T,g,h,f){const d=s("Link");return e(),l("div",null,[t[22]||(t[22]=p('<h1 id="安卓编年史-30-android-tv-和-android-auto" tabindex="-1">安卓编年史（30）：Android TV 和 Android Auto <a class="header-anchor" href="#安卓编年史-30-android-tv-和-android-auto" aria-label="Permalink to “安卓编年史（30）：Android TV 和 Android Auto”">​</a></h1><h3 id="android-tv" tabindex="-1">Android TV <a class="header-anchor" href="#android-tv" aria-label="Permalink to “Android TV”">​</a></h3><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/IMG_0002-22-1440x545.jpg" alt=""></p><p>2014 年 11 月谷歌公布了安卓 TV，安卓继续进行它带着一块屏幕征服一切的征程。这家公司里的一个部门之前在蜂巢时代尝试过用谷歌 TV 掌控客厅，但这次完全是来自安卓团队的新点子。安卓 TV 使用安卓 5.0 棒棒糖，并给了它一个为室内最大屏幕设计的 Material Design 界面。首发硬件谷歌选择了华硕来代工“Nexus Player”，这是一个配置不足但够用的机顶盒。</p><p>安卓 TV 专注于三样东西：视频，音乐，以及游戏。你可以用一个小遥控器控制电视，它只有四向方向键以及四个按钮，后退、主页、麦克风以及播放/暂停。至于游戏，华硕克隆了一个 Xbox 360 手柄，给了玩家一堆按键和一对摇杆。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2014/11/device-2014-10-31-172334.png" alt=""></p><p>安卓 TV 的界面很简单。大幅的媒体略缩图占据了屏幕，可以横向滚动，这些媒体中有 Youtube、Google Play、Netflix、Hulu 以及其它来源。这些略缩图实际上是来自不同媒体源的“推荐”项目，它不是简单地将一个应用的内容填满屏幕。在那下面你可以直接访问应用和设置。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2014/11/search-2.png" alt=""></p><p>语音界面很赞。你可以告诉安卓 TV 播放任意你想要的内容，而不用通过图形界面去寻找。你还能在内容里获得更聪明的搜索结果，比如“显示和 Harrison Ford 有关的电影”。每个应用都可以给索引服务提供内容，而不是简单的应用集合。所有的这些应用都在 Play 商店有一个 TV 版本。开发者对安卓 TV 的特别支持还包括谷歌 cast 协议，允许用户从他们的手机和平板向电视投射视频和音乐。</p><h3 id="android-5-1-lollipop" tabindex="-1">Android 5.1 Lollipop <a class="header-anchor" href="#android-5-1-lollipop" aria-label="Permalink to “Android 5.1 Lollipop”">​</a></h3>',10)),n("p",null,[t[1]||(t[1]=o("安卓 5.1 在 2015 年 3 月发布，这是安卓最小的更新。它的目的主要是",-1)),r(d,{href:"http://arstechnica.com/gadgets/2015/03/a-look-at-android-5-1-speed-security-tweaks/"},{default:i(()=>[...t[0]||(t[0]=[o("修复 Nexus 6 上的加密性能问题",-1)])]),_:1}),t[2]||(t[2]=o("，还添加了设备保护和一些小的界面调整。",-1))]),t[23]||(t[23]=n("p",null,[n("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2015/03/lock1.jpg",alt:""})],-1)),t[24]||(t[24]=n("p",null,[n("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2015/03/2015-03-14-17.33.58.png",alt:""})],-1)),t[25]||(t[25]=n("p",null,"设备保护是唯一的新增界面，采用的是在开机设置显示新警告的形式。这个特性在设备被偷了之后“保护你的设备不被再次利用”。一旦设置了锁屏，设备保护就开始介入，并且会在擦除设备的时候被触发。如果你以机主正常的方式擦除设备——解锁手机并从设置选择“重置”——什么都不会发生。但如果你通过开发者工具擦除，设备会在下次开机设置的时候要求你“验证之前同步的谷歌账户”。",-1)),t[26]||(t[26]=n("p",null,[n("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2015/03/screen-pin-2.jpg",alt:""})],-1)),t[27]||(t[27]=n("p",null,[n("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2015/03/time-picker.jpg",alt:""})],-1)),n("p",null,[t[4]||(t[4]=o("这个想法是基于开发者是会知道之前登录的谷歌帐号凭证的，但小偷就不知道了，他们会卡在设置这一步。在现实中这引发了",-1)),r(d,{href:"http://www.androidpolice.com/2016/08/11/rootjunky-discovers-frp-bypass-method-newer-samsung-phones/"},{default:i(()=>[...t[3]||(t[3]=[o("一个猫鼠游戏",-1)])]),_:1}),t[5]||(t[5]=o("，人们寻找漏洞来绕过设备保护，而谷歌知道了这个 bug 并修补它。OEM 定制也引入了一些有趣的 bug 来绕过设备保护。",-1))]),t[28]||(t[28]=p('<p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/03/icons.jpg" alt=""></p><p>还有很多特别微小的界面改动，我们没法一一列在上面的图中。除了上面的图片描述之外没什么可说的了。</p><h3 id="android-auto" tabindex="-1">Android Auto <a class="header-anchor" href="#android-auto" aria-label="Permalink to “Android Auto”">​</a></h3><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/Android_Auto_The_right_information_for_the_road_ahead_-_YouTube_-_Google_Chrome_2016-10-29_19-49-56-1440x810.jpg" alt=""></p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/Android-Auto-1440x882.jpg" alt=""></p><p>同样是在 2015 年 3 月，谷歌发布了“安卓 Auto”，一个基于安卓界面的全新车载娱乐信息系统。安卓 Auto 是谷歌面对苹果的 CarPlay 交出的答卷，它们很多地方都很相似。安卓 Auto 不完全是个操作系统——它是一个运行在你手机上的“投射”界面，使用车载显示屏作为一块外置显示器。运行安卓 Auto 意味着拥有一款兼容的汽车，在手机上（安卓 5.0 及以上版本）安装了安卓 Auto 应用，并用 USB 线将手机连接到汽车。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/07/screendump-2015-07-09-105548.png" alt=""></p><p>安卓 Auto 给你已有的车载系统带来了谷歌的 Material Design 界面，给这个[通常挣扎于]设计好软件的平台带来了顶级的软件设计。安卓 Auto 是个对安卓界面的完全重新设计，以遵循世界各地对车载系统无数的规定。它没有通常充满应用图标的“主屏”，安卓的导航栏也变为了一个常驻的应用启动器（几乎像是个标签页式的界面）。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/07/screendump-2015-07-10-113659.png" alt=""></p><p>算下来特性实际上只有四部分，导航栏从左到右是：谷歌地图，一个拨号/联系人界面，“主屏”部分混合了 Google Now 和一个通知面板，还有一个音乐页面。最后一个按钮是一个“OEM”页面，让你可以退出安卓 Auto，返回到自带的车载系统（这也是为了放置汽车制造商的定制特性）。安卓 Auto 还带有谷歌的语音命令系统，以一个麦克风按钮的形式显示在屏幕右上角。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/07/screendump-2015-07-09-091514.png" alt=""></p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/07/screendump-2015-07-09-110323.png" alt=""></p><p>安卓 Auto 的应用没有多少。它只允许两个类别的应用：音乐和信息应用。车载信息娱乐系统的规定意味着自定义界面不是个好选择。信息应用没有界面，并且可以接入语音系统，音乐应用也不会太多地改变界面，仅仅只是调整一下谷歌默认的“音乐应用”模板的颜色和图标。但实际上重要的是音乐和消息的送达，在不让驾驶员太多分心的情况下，一般的应用就没法使用了。</p>',13)),n("p",null,[t[7]||(t[7]=o("安卓 Auto 在它的最初发布之后就没看到多少更新了，但已经逐渐有很多汽车制造商支持了。到了 2017 年，将会有",-1)),r(d,{href:"http://www.usatoday.com/story/money/cars/2016/10/11/android-auto-comes-more-than-100-car-models-2017/91884366/"},{default:i(()=>[...t[6]||(t[6]=[o("超过 100",-1)])]),_:1}),t[8]||(t[8]=o(" 款支持的汽车型号。",-1))]),t[29]||(t[29]=n("hr",null,null,-1)),t[30]||(t[30]=n("p",null,"作者简介：",-1)),t[31]||(t[31]=n("p",null,"Ron 是 Ars Technica 的评论编缉，专注于安卓系统和谷歌产品。他总是在追寻新鲜事物，还喜欢拆解事物看看它们到底是怎么运作的。",-1)),t[32]||(t[32]=n("hr",null,null,-1)),n("p",null,[t[10]||(t[10]=o("via: ",-1)),r(d,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/30/"},{default:i(()=>[...t[9]||(t[9]=[o("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/30/",-1)])]),_:1})]),n("p",null,[t[14]||(t[14]=o("作者：",-1)),r(d,{href:"http://arstechnica.com/author/ronamadeo/"},{default:i(()=>[...t[11]||(t[11]=[o("RON AMADEO",-1)])]),_:1}),t[15]||(t[15]=o(" 译者：",-1)),r(d,{href:"https://github.com/alim0x"},{default:i(()=>[...t[12]||(t[12]=[o("alim0x",-1)])]),_:1}),t[16]||(t[16]=o(" 校对：",-1)),r(d,{href:"https://github.com/wxy"},{default:i(()=>[...t[13]||(t[13]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[19]||(t[19]=o("本文由 ",-1)),r(d,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[17]||(t[17]=[o("LCTT",-1)])]),_:1}),t[20]||(t[20]=o(" 原创编译，",-1)),r(d,{href:"https://linux.cn/"},{default:i(()=>[...t[18]||(t[18]=[o("Linux中国",-1)])]),_:1}),t[21]||(t[21]=o(" 荣誉推出",-1))])])}const y=a(u,[["render",A]]);export{V as __pageData,y as default};
